const extract = $('Extraer datos del mensaje').item.json;
const phone = extract.phone;
const pushName = (extract.pushName || '').replace(/'/g, "''").substring(0, 120);

return [{
  json: {
    phone,
    safeName: pushName,
    language: 'en',
    remoteJid: extract.remoteJid,
    messageText: extract.messageText,
    hasMedia: extract.hasMedia,
    mediaUrl: extract.mediaUrl
  }
}];

const ins = $json;
const extract = $('Preparar inserción nuevo lead').item.json;
const id = ins.id;

// Si el INSERT devolvió una fila, generar sku desde id
if (id) {
  const sku = String(id).padStart(4, '0');
  // Actualizar el sku en DB (lo haremos en el siguiente nodo)
  return [{ json: {
    leadId: id,
    sku: sku,
    leadName: ins.name || extract.safeName || '',
    language: ins.language || 'en',
    estado: ins.estado || 'captacion',
    phone: ins.phone || extract.phone,
    remoteJid: extract.remoteJid,
    messageText: extract.messageText,
    hasMedia: extract.hasMedia,
    mediaUrl: extract.mediaUrl,
    isNewLead: true
  }}];
}
// Fallback si no hay id
return [{ json: {
  leadId: null, sku: null, leadName: '', language: 'en',
  estado: 'captacion', phone: extract.phone,
  remoteJid: extract.remoteJid, messageText: extract.messageText,
  hasMedia: extract.hasMedia, mediaUrl: extract.mediaUrl, isNewLead: true
}}];

// === Cargar datos del lead desde cualquiera de las dos ramas ===
let leadData = null;
try {
  const ex = $('Preparar datos lead existente').item.json;
  if (ex && (ex.sku || ex.phone)) leadData = ex;
} catch(e) {}
if (!leadData || !leadData.sku) {
  try {
    const nl = $('Preparar datos nuevo lead').item.json;
    if (nl && (nl.sku || nl.phone)) leadData = nl;
  } catch(e) {}
}
if (!leadData) {
  leadData = { sku: null, leadName: '', language: '', estado: 'captacion', phone: '', remoteJid: '', messageText: '', hasMedia: false, mediaUrl: '' };
}

// === Sanitizar (escapar llaves para que no rompan el template) ===
function sanitize(text) {
  if (!text) return '';
  return String(text).replace(/\{/g, '{{').replace(/\}/g, '}}');
}

// === Formatear historial conversacional ===
const historialItems = $input.all();
const historial = historialItems
  .filter(h => h.json.rol && h.json.contenido)
  .slice(-20)
  .map(h => (h.json.rol === 'user' ? 'Lead' : 'Bot') + ': ' + sanitize(h.json.contenido))
  .join('\n');

// === Idioma: si ya está fijado en DB, la IA lo respeta. Si no, la IA lo detecta. ===
const langDirective = (leadData.language && leadData.language.length === 2)
  ? 'LANGUAGE LOCKED TO: ' + (leadData.language === 'es' ? 'SPANISH' : 'ENGLISH')
  : 'LANGUAGE: NOT YET SET — detect the language from the current message and respond in that language. Include your detected language code in the JSON output.';

// === Construir mensaje para el AI Agent (solo datos dinámicos) ===
const userMessage = [
  'LEAD STATE: ' + leadData.estado,
  'LEAD NAME: ' + (leadData.leadName || 'unknown'),
  langDirective,
  'HAS MEDIA IN CURRENT MESSAGE: ' + (leadData.hasMedia ? 'true' : 'false'),
  '',
  'CONVERSATION HISTORY:',
  historial || '(no prior messages)',
  '',
  'CURRENT MESSAGE FROM LEAD: ' + (sanitize(leadData.messageText) || '(media only — no text)')
].join('\n');

return [{
  json: {
    ...leadData,
    historialFormateado: historial,
    userMessage
  }
}];

const ctx = $('Preparar contexto para agente').item.json;
let out = $json.output;

// === Resolver la salida en sus 3 formas posibles ===
let parsed = null;
if (out && typeof out === 'object') {
  // El Structured Output Parser entregó objeto directo
  parsed = out;
} else {
  const text = (out || $json.text || $json.response || '').toString().trim();
  // Intentar extraer JSON embebido en texto
  try {
    const m = text.match(/\{[\s\S]*\}/);
    if (m) parsed = JSON.parse(m[0]);
  } catch(e) {}
  // Si no hay JSON pero sí texto plano, usar el texto como mensaje (red de seguridad)
  if (!parsed && text) {
    parsed = { message: text, newState: ctx.estado, sendImage: false, intent: 'plaintext', language: ctx.language || 'en' };
  }
}

// === Fallback final si todo falló ===
if (!parsed) {
  parsed = {
    message: (ctx.language === 'es')
      ? 'Disculpa, tuve un pequeño inconveniente. ¿Puedes repetir tu mensaje? 🙏'
      : 'Sorry, I had a small hiccup. Could you repeat your message? 🙏',
    newState: ctx.estado, sendImage: false, intent: 'parse_failed', language: ctx.language || 'en'
  };
}

const agentMessage = (parsed.message || '').replace(/\\n/g, '\n');
const newState = parsed.newState || ctx.estado;
const sendImage = parsed.sendImage === true && newState === 'fotos_solicitadas';
const language = (parsed.language === 'es' || parsed.language === 'en') ? parsed.language : (ctx.language || 'en');

return [{
  json: {
    sku:            ctx.sku,
    phone:          ctx.phone,
    remoteJid:      ctx.remoteJid,
    estadoAnterior: ctx.estado,
    messageText:    ctx.messageText,
    agentMessage,
    newState,
    sendImage,
    imageCaption:   parsed.imageCaption || '',
    intent:         parsed.intent || '',
    language
  }
}];

// Recuperar contexto del paso de parseo
const ctx = $('Parsear respuesta del agente').item.json;

// Dos filas: mensaje entrante del lead + respuesta del bot.
// La fila del bot guarda el 'intent' que la IA entendió (observabilidad / debug).
return [
  {
    json: {
      lead_sku: ctx.sku,
      rol: 'user',
      contenido: ctx.messageText || '',
      media_url: null,
      intent: null
    }
  },
  {
    json: {
      lead_sku: ctx.sku,
      rol: 'assistant',
      contenido: ctx.agentMessage || '',
      media_url: null,
      intent: ctx.intent || null
    }
  }
];

const lead = $('Parsear respuesta del agente').item.json;
const ctx  = $('Preparar contexto para agente').item.json;

const sku    = lead.sku || '????';
const nombre = ctx.leadName || 'Sin nombre';
const idioma = lead.language === 'es' ? 'Español' : 'English';
const fecha  = new Date().toLocaleString('es-CO', { timeZone: 'America/Bogota' });

const msg = '📋 NUEVO CASO'
  + '\nSKU: ' + sku
  + '\nNombre: ' + nombre
  + '\nIdioma: ' + idioma
  + '\nFecha: ' + fecha
  + '\n\nResponde con:'
  + '\n' + sku + ' VIABLE: [cotización]'
  + '\n' + sku + ' FALTA INFO: [qué falta]'
  + '\n' + sku + ' NO VIABLE: [motivo]';

return [{ json: { groupMsg: msg, sku, nombre } }];

const ext = $('Extraer datos del mensaje').item.json;
return [{json: {
  b64Body: JSON.stringify({
    message: {
      key: { remoteJid: ext.remoteJid, fromMe: false, id: ext.messageId },
      messageType: 'imageMessage'
    }
  })
}}];

const b64data = $('Obtener base64 de imagen').item.json;
const sku = $('Preparar mensaje grupo').item.json.sku;
const groupId = ($env['WHATSAPP_GROUP_CASOS'] || '').replace('@g.us','');

return [{json: {
  sendMediaBody: JSON.stringify({
    number: groupId,
    mediatype: 'image',
    mimetype: b64data.mimetype || 'image/jpeg',
    caption: 'SKU: ' + sku,
    media: b64data.base64
  })
}}];

// Restaurar el contexto del mensaje original.
// El nodo Postgres 'Verificar duplicado' solo devuelve message_id por el RETURNING,
// así que los campos extraídos por 'Extraer datos del mensaje' se pierden en el flujo.
// Aquí los volvemos a inyectar para que los nodos downstream funcionen igual que antes.
const orig = $('Extraer datos del mensaje').item.json;
return [{ json: { ...orig, message_id: $json.message_id } }];

